@click.command("routes", short_help="Show the routes for the app.")
@click.option(
    "--sort",
    "-s",
    type=click.Choice(("endpoint", "methods", "rule", "match")),
    default="endpoint",
    help=(
        'Method to sort routes by. "match" is the order that Flask will match '
        "routes when dispatching a request."
    ),
)
@click.option("--all-methods", is_flag=True, help="Show HEAD and OPTIONS methods.")
@click.option("--all-domains", is_flag=True, help="Show rules that apply to all domains.")
@click.option(
    "--host",
    "-h",
    default=None,
    help=(
        "Show the domain, port, and scheme of the routes, based on this host. "
        "Defaults to the value of SERVER_NAME if it is set."
    ),
)
@with_appcontext
def routes_command(
    sort: str, all_methods: bool, all_domains: bool, host: str | None
) -> None:
    """Show all registered routes with endpoints and methods."""
    rules = list(current_app.url_map.iter_rules())

    if not rules:
        click.echo("No routes were registered.")
        return

    ignored_methods = set() if all_methods else {"HEAD", "OPTIONS"}
    ignored_rule = None

    if not all_domains:
        ignored_rule = current_app.url_map.default_subdomain

    should_show_domain = all_domains or any(
        rule.subdomain_for(host) != ignored_rule for rule in rules
    )

    headers: list[str] = []

    if should_show_domain:
        headers.append("Domain")

    headers += ["Endpoint", "Methods", "Rule"]
    widths: list[int] = [len(header) for header in headers]
    data = []

    for rule in rules:
        if not all_domains and rule.subdomain_for(host) == ignored_rule:
            continue

        rule_methods = ", ".join(sorted(rule.methods - ignored_methods))  # type: ignore
        row_data = []

        if should_show_domain:
            row_data.append(rule.domain_for(host))

        row_data += [rule.endpoint, rule_methods, rule.rule]
        data.append(row_data)

        for i, value in enumerate(row_data):
            widths[i] = max(widths[i], len(value))

    row_format = "  ".join(f"{{:{'<' if i == idx else '>'}{w}}}" for i, (idx, w) in enumerate(zip(range(len(widths)), widths)))

    click.echo(row_format.format(*headers).strip())
    click.echo(row_format.format(*(("-" * width for width in widths))))

